namespace ModConfigEnhance;

/// <summary>config\ModConfigEnhance\readme.md 的内容，按当前界面语言挑一份（C# 原始字符串；{VERSION} 由 Loc 替换）。
/// 2.5.0 重写：只讲这个目录和语言文件怎么用；功能介绍在游戏内「使用说明」与项目 README。</summary>
internal static class LanguageReadme
{
    internal static string For(Loc.UiLang lang) => lang switch
    {
        Loc.UiLang.ZhCn => ZhCn,
        Loc.UiLang.ZhTw => ZhTw,
        _ => En,
    };

    private const string En = """
        # In-Game Mod Manager {VERSION} · language files

        *Generated by the mod: rewritten on every launch and language change, in the current interface language. Edits to this file are overwritten.*

        ## What lives here

        - `language\` — your language files, one per language: `zh-cn.txt`, `zh-tw.txt`, `de-de.txt` …
        - `profiles\` — configuration profiles, the modpack introduction and its media
        - `output\` — things you export: `translation\` (**Export texts** / **Untranslated**), `packs\` (published modpacks), `logs\` (log exports when Save As is unavailable)
        - `data\` — the manager's own data: `runtime\` state and store caches, `backups\` automatic backups, `help\` your guide edits, `legacy\` data from before October 2026
        - `readme.md` — this file

        English is the source text; Simplified and Traditional Chinese are built in, so no file is needed for them. A file is only for **your own** translations and changes. Files starting with `_` never show in the dropdown, and subfolders are ignored — put backups there.

        Lookup order for every text: your file → the active modpack's author file → built-in → English original.

        ## File format

        One entry per line: `original=translation`.

        - `//` starts a comment. The first line `// display: Name` sets the name shown in the language dropdown.
        - Inside text, `\n` is a line break and `\=` an equals sign. Keep `{0}` `{1}` placeholders.
        - **Never change the left side of `=`**: it must match the on-screen text character for character.
        - `IGMM_KEY=text` lines change this manager's own interface text (the key is a fixed ID; translate the right side only). Leave them out to use the built-in text.
        - Empty right side = not translated, the original shows.

        ### Regex rules

        For texts that differ only by a number or a name:

        ```text
        r:"^(\d+) players online$"=$1 players online (translated)
        r:"^Level (?<n>\d+)$"=Level ${n} (translated)
        ```

        - Same format as XUnity AutoTranslator dictionaries, so rules can be copied from there.
        - `$1` refers to the first group in brackets, `${name}` to a named group.
        - Exact lines win over regex rules; among regex rules the one written **later** wins.
        - A broken rule is skipped and reported with its line number when the language is applied.

        ## Adding or improving a language

        1. **Export** — settings page, left column: **Export texts** (everything) or **Untranslated** (only what the current language lacks). Tick **Selected only** to limit it to some mods.
        2. **Translate** — fill in the right side of each `=`, save as UTF-8.
        3. **Import** — click **Import additions** and pick the file. Every filled-in line is merged into the current language file (`language\<code>.txt`); the same original is replaced by the imported one, empty lines are skipped, the old file is backed up next to it.
        4. A **new** language: save the exported file as `language\<code>.txt` (`de-de.txt`, `ja-jp.txt` …), click the refresh button in the language row and pick it.

        After editing a language file by hand, click **Reload texts**.

        ## Language names

        - The file name is the language code (`xx` or `xx-yy`). `zh` = `zh-cn`, `en` = `en-us`.
        - `code-variant.txt` (e.g. `zh-cn-old.txt`) is a separate translation of the same language with its own entry in the dropdown.
        - **Follow game language** picks the file whose name equals the game's language code.

        ## Toolbar

        - **Export texts** / **Untranslated** / **Selected only** — see above.
        - **Show original / Show translated** — switches mod texts shown by this manager (sidebar, overview, description panel, settings page) to the original for comparison. The manager's own interface keeps the chosen language.
        - **Reload texts** — re-reads the language files.
        - **Import additions** — merges a filled-in export file into the current language file.
        - Folder button — opens this directory.

        ## XUnity AutoTranslator

        Not needed: all translation is done by these language files. If XUnity is installed with online machine translation on (`Endpoint` in `AutoTranslatorConfig.ini` is not empty), the manager reminds you once per launch — the two would mix — and can turn its machine translation off for you (the ini is backed up first). Option: `2. Localization / Warn about XUnity machine translation`.

        Feedback and translations: `2323086800@qq.com` · QQ group `1104320838` · https://github.com/AiAe-156/Peak-InGameModManager

        """;

    private const string ZhCn = """
        # 游戏内模组管理器 {VERSION} · 语言文件说明

        *本文件由模组自动生成：每次启动和切换语言后按当前界面语言重写，手工改动会被覆盖。*

        ## 这个目录放什么

        - `language\`：你的语言文件，一种语言一个：`zh-cn.txt`、`zh-tw.txt`、`de-de.txt`……
        - `profiles\`：配置方案、整合包介绍和介绍里的素材
        - `output\`：你导出的东西：`translation\`（「导出翻译」「补漏翻」）、`packs\`（发布的整合包）、`logs\`（「另存为」打不开时的日志导出）
        - `data\`：管理器自己的数据：`runtime\` 运行状态和商店缓存、`backups\` 自动备份、`help\` 你改过的使用说明、`legacy\` 2026 年 10 月以前的旧数据
        - `readme.md`：本说明

        英文是原文，简体和繁体中文已经内置，不需要文件。语言文件只放**你自己的**翻译和改动。`_` 开头的文件不进下拉框，子目录不读——备份放子目录里。

        每一句文字按这个顺序找：你的文件 → 当前整合包作者的文件 → 内置 → 英文原文。

        ## 文件格式

        每行一条：`原文=译文`。

        - `//` 开头是注释。首行 `// display: 名字` 决定语言下拉框里显示的名字。
        - 文字里 `\n` 是换行，`\=` 是等号；`{0}` `{1}` 占位符原样保留。
        - **等号左边一个字都别改**：它要和屏幕上的原文逐字一致才对得上。
        - `IGMM_键=文字` 的行用来改本管理器自己的界面文字（键是固定 ID，只改右边）。不写就用内置文字。
        - 等号右边留空 = 未翻，显示原文。

        ### 正则规则

        只差数字或名字的句子用正则：

        ```text
        r:"^(\d+) players online$"=$1 名玩家在线
        r:"^Level (?<n>\d+)$"=第 ${n} 关
        ```

        - 格式和 XUnity AutoTranslator 词典一样，可以直接从它那边搬。
        - `$1` 引用第一个括号里的内容，`${名字}` 引用命名分组。
        - 整句译文优先于正则；多条正则都能命中时，**写在后面的**优先。
        - 写错的规则会跳过，应用语言时在说明面板提示是第几行。

        ## 补翻或新增语言

        1. **导出**：设置页左栏「导出翻译」（全部）或「补漏翻」（只要当前语言还没翻的）。勾「仅导出已选」可以只导出部分模组。
        2. **翻译**：把译文填在每个 `=` 右边，用 UTF-8 保存。
        3. **导入**：点「导入补翻」选这个文件。填好的行会合进当前语言文件（`language\<语言码>.txt`）：同一句原文以导入的为准，留空的行跳过，原文件先在旁边备份。
        4. **新语言**：把导出文件另存为 `language\<语言码>.txt`（`de-de.txt`、`ja-jp.txt`……），点语言行的刷新按钮，再在下拉框里选它。

        手动改过语言文件后，点「重载翻译」生效。

        ## 文件名

        - 文件名就是语言码（`xx` 或 `xx-yy`）。`zh` = `zh-cn`，`en` = `en-us`。
        - `语言码-变体.txt`（如 `zh-cn-old.txt`）是同一语言的另一套翻译，在下拉框里单独一项。
        - 「跟随游戏语言」选文件名等于游戏语言码的那个文件。

        ## 工具行

        - 「导出翻译」「补漏翻」「仅导出已选」：见上。
        - 「显示原文 / 显示译文」：把本管理器负责显示的模组文字（侧栏、概览、说明面板、设置页）切成原文对照。管理器自己的界面保持所选语言。
        - 「重载翻译」：重读语言文件。
        - 「导入补翻」：把填好的导出文件合进当前语言文件。
        - 文件夹按钮：打开本目录。

        ## XUnity AutoTranslator

        不需要它：翻译全部由这里的语言文件完成。如果装了 XUnity 并且开着在线机翻（`AutoTranslatorConfig.ini` 的 `Endpoint` 不为空），两边的译文会混在一起，管理器每次启动会提醒一次，并可以替你关掉它的在线机翻（先备份 ini）。开关：`2. Localization / Warn about XUnity machine translation`。

        问题反馈和投稿译文：`2323086800@qq.com` · QQ 群 `1104320838` · https://github.com/AiAe-156/Peak-InGameModManager

        """;

    private const string ZhTw = """
        # 遊戲內模組管理器 {VERSION} · 語言檔案說明

        *本檔案由模組自動產生：每次啟動和切換語言後按目前介面語言重寫，手動修改會被覆蓋。*

        ## 這個目錄放什麼

        - `language\`：你的語言檔案，一種語言一個：`zh-cn.txt`、`zh-tw.txt`、`de-de.txt`……
        - `profiles\`：設定方案、整合包介紹和介紹裡的素材
        - `output\`：你匯出的東西：`translation\`（「匯出翻譯」「補漏翻」）、`packs\`（發佈的整合包）、`logs\`（「另存新檔」打不開時的日誌匯出）
        - `data\`：管理器自己的資料：`runtime\` 執行狀態和商店快取、`backups\` 自動備份、`help\` 你改過的使用說明、`legacy\` 2026 年 10 月以前的舊資料
        - `readme.md`：本說明

        英文是原文，簡體和繁體中文已經內建，不需要檔案。語言檔案只放**你自己的**翻譯和修改。`_` 開頭的檔案不進下拉選單，子目錄不讀——備份放子目錄裡。

        每一句文字按這個順序找：你的檔案 → 目前整合包作者的檔案 → 內建 → 英文原文。

        ## 檔案格式

        每行一條：`原文=譯文`。

        - `//` 開頭是註解。首行 `// display: 名字` 決定語言下拉選單裡顯示的名字。
        - 文字裡 `\n` 是換行，`\=` 是等號；`{0}` `{1}` 佔位符原樣保留。
        - **等號左邊一個字都別改**：它要和螢幕上的原文逐字一致才對得上。
        - `IGMM_鍵=文字` 的行用來改本管理器自己的介面文字（鍵是固定 ID，只改右邊）。不寫就用內建文字。
        - 等號右邊留空 = 未翻，顯示原文。

        ### 正則規則

        只差數字或名字的句子用正則：

        ```text
        r:"^(\d+) players online$"=$1 名玩家在線
        r:"^Level (?<n>\d+)$"=第 ${n} 關
        ```

        - 格式和 XUnity AutoTranslator 詞典一樣，可以直接從它那邊搬。
        - `$1` 引用第一個括號裡的內容，`${名字}` 引用命名分組。
        - 整句譯文優先於正則；多條正則都能命中時，**寫在後面的**優先。
        - 寫錯的規則會略過，套用語言時在說明面板提示是第幾行。

        ## 補翻或新增語言

        1. **匯出**：設定頁左欄「匯出翻譯」（全部）或「補漏翻」（只要目前語言還沒翻的）。勾「僅匯出已選」可以只匯出部分模組。
        2. **翻譯**：把譯文填在每個 `=` 右邊，用 UTF-8 儲存。
        3. **匯入**：點「匯入補翻」選這個檔案。填好的行會合進目前語言檔案（`language\<語言碼>.txt`）：同一句原文以匯入的為準，留空的行略過，原檔案先在旁邊備份。
        4. **新語言**：把匯出檔案另存為 `language\<語言碼>.txt`（`de-de.txt`、`ja-jp.txt`……），點語言列的重新整理按鈕，再在下拉選單裡選它。

        手動改過語言檔案後，點「重載翻譯」生效。

        ## 檔名

        - 檔名就是語言碼（`xx` 或 `xx-yy`）。`zh` = `zh-cn`，`en` = `en-us`。
        - `語言碼-變體.txt`（如 `zh-cn-old.txt`）是同一語言的另一套翻譯，在下拉選單裡單獨一項。
        - 「跟隨遊戲語言」選檔名等於遊戲語言碼的那個檔案。

        ## 工具列

        - 「匯出翻譯」「補漏翻」「僅匯出已選」：見上。
        - 「顯示原文 / 顯示譯文」：把本管理器負責顯示的模組文字（側欄、概覽、說明面板、設定頁）切成原文對照。管理器自己的介面保持所選語言。
        - 「重載翻譯」：重讀語言檔案。
        - 「匯入補翻」：把填好的匯出檔案合進目前語言檔案。
        - 資料夾按鈕：打開本目錄。

        ## XUnity AutoTranslator

        不需要它：翻譯全部由這裡的語言檔案完成。如果裝了 XUnity 並且開著線上機翻（`AutoTranslatorConfig.ini` 的 `Endpoint` 不為空），兩邊的譯文會混在一起，管理器每次啟動會提醒一次，並可以替你關掉它的線上機翻（先備份 ini）。開關：`2. Localization / Warn about XUnity machine translation`。

        問題回報和投稿譯文：`2323086800@qq.com` · QQ 群 `1104320838` · https://github.com/AiAe-156/Peak-InGameModManager

        """;
}
